select DATE_FORMAT(trans_date,'%Y-%m') as month,country,count(*)as trans_count,
count(CASE when state="approved" then 1 end)as approved_count ,SUM(amount) AS trans_total_amount,sum(CASE when state='Approved' then amount else 0 end)as approved_total_amount from Transactions group by DATE_FORMAT(trans_date,'%Y-%m'),country;